Inline Assembly (GCC):
#include <stdio.h>

int main() {
    int a = 10, b = 20, result;

    asm("add %1, %0"
        : "+r" (a)
        : "r" (b)
    );
    printf("a + b = %d\n", a);

    int x = 42, y = 0;
    asm volatile(
        "mov %0, %1\n\t"
        "add %0, 10"
        : "=r" (y)
        : "r" (x)
    );
    printf("y = %d\n", y);

    long long rax_val;
    asm("mov %%rax, %0" : "=r" (rax_val));
    printf("RAX = 0x%lx\n", rax_val);

    return 0;
}
